{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Pamatolol, a close aryloxypropanolamine beta-blocker with an isopropylamino group and para carbamate substituent, showed essentially complete oral bioavailability versus identical IV doses, supporting high F for the query's similar tert-butylamino aryloxypropanolamine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Practolol, another para-substituted phenoxypropanolamine beta-blocker, had absolute oral bioavailability of 90–100% in humans, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Diacetolol, a more polar para-acetamido phenoxypropanolamine, had mean F of 0.426 ± 0.068 at 800 mg, still well above the 20% threshold, indicating that even less bioavailable analogues in this class exceed the cutoff.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pindolol, an aryloxypropanolamine beta-blocker, had absolute F of 86 ± 7% in patients without renal impairment, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Bufuralol, which shares the tert-butylamino hydroxypropoxy motif, showed systemic availability of 0.52–0.83 in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All highly transferable experimental analogues are beta-blockers or related aryloxypropanolamines with measured oral bioavailability well above 20%, mostly 50–100%. The query's structural similarity to these high-F compounds supports a high prediction. Rifampin co-treatment could lower exposure through P-gp/CYP3A4 induction, but the high baseline F of close analogues makes a drop below 20% unlikely.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the exact query molecule.",
    "No rifampin co-treatment data for the query or its closest analogue talinolol are provided in the evidence set.",
    "The magnitude of any rifampin-mediated reduction in F for this specific urea beta-blocker is not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

